// Assemble the Flash-Lite narration prompt (§3.3).
// Guardrail (§2): OHLC candle arrays never traverse the LLM — the prompt
// carries only the computed indicator values and the short service summaries.
const trigger = $('When Executed by Another Workflow').first().json;
const ind = $('Fetch Indicators').first().json;
const ohlc = $('Fetch OHLC').first().json;

const inputsOk = Boolean(ind.as_of) && !!ind.indicators && Object.keys(ind.indicators).length > 0;
const degradeReason = inputsOk
  ? null
  : `quant service returned no indicators (${ind.summary || (ind.error && ind.error.message) || ohlc.summary || 'no data'})`;

const prompt = [
  `You are the Technical Agent for TA-35 ticker ${ind.symbol}.`,
  `As of ${ind.as_of}, computed indicators (RSI 14, MACD 12/26/9, Bollinger 20/2, ATR 14):`,
  JSON.stringify(ind.indicators),
  `Quant service note: ${ind.summary}`,
  '',
  'Write a plain-English reading of these indicators and classify the technical signal.',
  'Respond with ONLY a JSON object, no markdown fences, exactly this shape:',
  '{"signal": "<one of: bullish_momentum, bearish_momentum, overbought, oversold, neutral>", "summary": "<at most 2 sentences, under 500 characters>"}',
  'Base the reading strictly on the numbers provided. Treat null values as unavailable — do not guess them.',
].join('\n');

return [{
  json: {
    ticker: trigger.ticker,
    run_id: trigger.run_id,
    as_of: ind.as_of,
    indicators: ind.indicators,
    inputs_ok: inputsOk,
    degrade_reason: degradeReason,
    prompt,
  },
}];

// Parse the raw LLM text into a candidate payload for POST /validate.
// A parse failure is NOT swallowed — it becomes an invalid payload so the
// validate → retry → degraded path handles it (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return [{ json: { agent: 'technical', payload, raw } }];

// §3.3 output + §3.4 canonical status. Indicator numbers come from the
// quant service context, never from the LLM.
const ctx = $('Build Prompt').first().json;
const narration = $('Parse Narration').first().json.payload;
return [{
  json: {
    ticker: ctx.ticker,
    as_of: ctx.as_of,
    indicators: ctx.indicators,
    signal: narration.signal,
    summary: narration.summary,
    status: 'ok',
  },
}];

// One automatic retry with a stricter instruction (§9.4). The validation
// errors from POST /validate are quoted back to the model.
const ctx = $('Build Prompt').first().json;
const errors = $json.errors || [];
const prompt = ctx.prompt
  + '\n\nYour previous response was rejected by schema validation: '
  + JSON.stringify(errors)
  + '\nRespond again with ONLY the JSON object described above — no prose, no markdown fences, no extra keys. '
  + '"signal" MUST be exactly one of: bullish_momentum, bearish_momentum, overbought, oversold, neutral.';
return [{ json: { prompt } }];

const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return [{ json: { agent: 'technical', payload, raw } }];

const ctx = $('Build Prompt').first().json;
const narration = $('Parse Retry Narration').first().json.payload;
return [{
  json: {
    ticker: ctx.ticker,
    as_of: ctx.as_of,
    indicators: ctx.indicators,
    signal: narration.signal,
    summary: narration.summary,
    status: 'ok',
  },
}];

// Degraded result (§9.4): no fabrication, explicit reason, neutral signal.
// Reached either when the quant service had no data (Inputs OK? = false)
// or when the narration failed validation twice.
const ctx = $('Build Prompt').first().json;
let reason;
if (ctx.inputs_ok === false) {
  reason = ctx.degrade_reason || 'no indicator data from quant service';
} else {
  let errors = [];
  try { errors = $('Validate Retry').first().json.errors || []; } catch (e) { /* retry branch never ran */ }
  reason = 'LLM narration failed schema validation after one stricter retry'
    + (errors.length ? ` (${errors.join('; ')})` : '');
}
return [{
  json: {
    ticker: ctx.ticker,
    as_of: ctx.as_of || null,
    indicators: ctx.indicators || {},
    signal: 'neutral',
    summary: `degraded: ${reason}`,
    status: 'degraded',
  },
}];
